  alertThreshold: boolean;
  rounding: boolean;
};

const UNTOUCHED: Touched = {
  clerkLimit: false,
  floor: false,
  terms: false,
  latePct: false,
  policyDate: false,
  periodNumberingFrom: false,
  entryDate: false,
  cap: false,
